CREATE TABLE IF NOT EXISTS personal_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS notes_owner ON personal_notes(owner_id);
CREATE TABLE IF NOT EXISTS reference_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, value TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS inventory_comments (id INTEGER PRIMARY KEY AUTOINCREMENT, inventory_id INTEGER NOT NULL REFERENCES inventory(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_loans (id INTEGER PRIMARY KEY AUTOINCREMENT, inventory_id INTEGER NOT NULL REFERENCES inventory(id), borrower_id TEXT NOT NULL REFERENCES users(id), issued_by TEXT NOT NULL REFERENCES users(id), comment TEXT NOT NULL DEFAULT '', issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, returned_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS inventory_active_loan ON inventory_loans(inventory_id) WHERE returned_at IS NULL;
CREATE TABLE IF NOT EXISTS key_public_links (key_id INTEGER PRIMARY KEY REFERENCES keys(id) ON DELETE CASCADE, public_id TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS key_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, key_id INTEGER NOT NULL REFERENCES keys(id), name TEXT NOT NULL, affiliation TEXT NOT NULL, purpose TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), responsible_id TEXT REFERENCES users(id), reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
